//! The level editor's document: what the original editor holds on its canvas, how it reads level XML into it (`buildLevel`)
//! and how it writes it back (`createXML`). Property defaults and limits are in `data/editor-schema.json`
//! (generated by `analysis/editor-schema.py` from the running original); the output is compared byte for byte with the
//! original's in `tests/editor.rs`.
//!
//! Not modelled: while editing, the original also pushes objects back inside the 20000×10000 canvas using their drawn bounds.

use anyhow::{bail, Context, Result};
use roxmltree::Node;
use serde::Deserialize;
use std::f64::consts::PI;

/// A property value as the original keeps it.
#[derive(Clone, Debug, PartialEq, Deserialize)]
#[serde(untagged)]
pub enum Value {
    Null,
    Bool(bool),
    Num(f64),
    Text(String),
}

impl Value {
    /// JavaScript's `Number(value)`.
    pub fn number(&self) -> f64 {
        match self {
            Value::Null => 0.0,
            Value::Bool(b) => f64::from(u8::from(*b)),
            Value::Num(n) => *n,
            Value::Text(s) if s.trim().is_empty() => 0.0,
            Value::Text(s) => s.trim().parse().unwrap_or(f64::NAN),
        }
    }

    pub fn truthy(&self) -> bool {
        match self {
            Value::Null => false,
            Value::Bool(b) => *b,
            Value::Num(n) => *n != 0.0 && !n.is_nan(),
            Value::Text(s) => !s.is_empty(),
        }
    }

    /// JavaScript's `String(value)`.
    fn text(&self) -> String {
        match self {
            Value::Null => "null".into(),
            Value::Bool(b) => b.to_string(),
            Value::Num(n) => js_number(*n),
            Value::Text(s) => s.clone(),
        }
    }
}

#[derive(Clone, Copy, Debug, Deserialize)]
#[serde(rename_all = "lowercase")]
pub enum Rule {
    Plain,
    /// Wrapped once into ±180, rounded, and kept in radians by the original (so 15 reads back as 14.999999999999998).
    Angle,
    /// `true` is ignored for objects inside a group.
    Immovable,
    /// Like `Immovable`, for the "interactive" flag of specials.
    Interactive,
    /// 0..100, read back rounded.
    Opacity,
    /// Glass shatter strength: 0 means 10.
    Strength,
    Clamp(Option<f64>, Option<f64>),
    /// Width or height kept as a scale of `div` pixels, the scale clamped.
    Size(f64, Option<f64>, Option<f64>),
    /// Circle and meteor: either dimension sets both.
    Both(f64, Option<f64>, Option<f64>),
    /// Polygon and art: scale relative to the bounds of the vertices; 0 is ignored.
    Poly(Option<f64>, Option<f64>),
    Fixed(f64),
}

#[derive(Debug, Deserialize)]
pub struct Class {
    pub name: String,
    pub props: Vec<(String, Value, Rule)>,
    /// Parameters per trigger action; `None` when the object cannot be an action target.
    pub actions: Option<Vec<usize>>,
}

#[derive(Debug, Deserialize)]
pub struct Schema {
    pub shapes: Vec<Class>,
    pub specials: Vec<Class>,
    actions: std::collections::HashMap<String, Option<Vec<usize>>>,
    pub version: f64,
    #[serde(rename = "versionString")]
    pub version_string: String,
}

pub fn schema() -> &'static Schema {
    static SCHEMA: std::sync::OnceLock<Schema> = std::sync::OnceLock::new();
    SCHEMA.get_or_init(|| serde_json::from_str(include_str!("../data/editor-schema.json")).expect("editor schema"))
}

const POLYGON: usize = 3;
const ART: usize = 4;
/// Entries of the original's sound list a sound trigger can pick.
const SOUNDS: f64 = 326.0;

#[derive(Clone, Debug, Default)]
pub struct Vertices {
    pub id: i64,
    pub filled: bool,
    /// Point and the two bezier handles (zero for polygons).
    pub points: Vec<[[f64; 2]; 3]>,
}

/// A shape or a special object.
#[derive(Clone, Debug)]
pub struct Item {
    /// Index into the schema's shape or special list.
    pub class: usize,
    pub special: bool,
    pub grouped: bool,
    /// Shapes only: `false` makes it artwork.
    pub interactive: bool,
    pub vehicle_handle: bool,
    /// One per schema property.
    pub values: Vec<Value>,
    pub vertices: Option<Vertices>,
}

impl Item {
    pub fn new(special: bool, class: usize, grouped: bool) -> Option<Item> {
        let list = if special { &schema().specials } else { &schema().shapes };
        let c = list.get(class)?;
        Some(Item {
            class,
            special,
            grouped,
            interactive: special || class != ART,
            vehicle_handle: false,
            values: c.props.iter().map(|p| p.1.clone()).collect(),
            vertices: None,
        })
    }

    pub fn spec(&self) -> &'static Class {
        let s = schema();
        let list = if self.special { &s.specials } else { &s.shapes };
        &list[self.class]
    }

    fn index(&self, name: &str) -> Option<usize> {
        self.spec().props.iter().position(|p| p.0 == name)
    }

    pub fn get(&self, name: &str) -> Option<&Value> {
        self.index(name).map(|i| &self.values[i])
    }

    /// The property setter, with the original's limits.
    pub fn set(&mut self, name: &str, value: Value) {
        let Some(i) = self.index(name) else { return };
        let rule = self.spec().props[i].2;
        match rule {
            Rule::Plain => self.values[i] = value,
            Rule::Angle => self.values[i] = Value::Num(round_angle(value.number())),
            Rule::Immovable | Rule::Interactive => {
                if !(value.truthy() && self.grouped) {
                    self.values[i] = value;
                }
            }
            Rule::Opacity => self.values[i] = Value::Num(js_round(100.0 * (0.01 * clamp(value.number(), Some(0.0), Some(100.0))))),
            Rule::Strength => {
                let v = if value.number() == 0.0 { 10.0 } else { value.number() };
                self.values[i] = Value::Num(clamp(v, Some(1.0), Some(10.0)));
            }
            Rule::Clamp(lo, hi) => self.values[i] = Value::Num(clamp(value.number(), lo, hi)),
            Rule::Size(div, lo, hi) => self.values[i] = Value::Num(js_round(div * clamp(value.number() / div, lo, hi))),
            Rule::Both(div, lo, hi) => {
                let v = Value::Num(js_round(div * clamp(value.number() / div, lo, hi)));
                for name in ["shapeWidth", "shapeHeight"] {
                    if let Some(j) = self.index(name) {
                        self.values[j] = v.clone();
                    }
                }
            }
            Rule::Poly(lo, hi) => {
                if value.number() != 0.0 {
                    let size = self.default_size(usize::from(name == "shapeHeight"));
                    let scale = if size > 0.0 { value.number() / size } else { 1.0 };
                    self.values[i] = Value::Num(js_round(size * clamp(scale, lo, hi)));
                }
            }
            Rule::Fixed(v) => self.values[i] = Value::Num(v),
        }
    }

    /// Width (`axis` 0) or height of the box around the vertices and the shape's own origin (`setDefaultDimensions`; curves do not count).
    fn default_size(&self, axis: usize) -> f64 {
        let Some(v) = self.vertices.as_ref() else { return 0.0 };
        let (lo, hi) = v.points.iter().fold((0.0f64, 0.0f64), |(lo, hi), p| (lo.min(p[0][axis]), hi.max(p[0][axis])));
        hi - lo
    }
}

#[derive(Clone, Debug, Default)]
pub struct Vehicle {
    pub space_action: f64,
    pub shift_action: f64,
    pub ctrl_action: f64,
    pub acceleration: f64,
    pub leaning_strength: f64,
    pub character_pose: f64,
    pub lock_joints: bool,
}

#[derive(Clone, Debug, Default)]
pub struct Group {
    pub x: f64,
    pub y: f64,
    pub angle: f64,
    pub offset: [f64; 2],
    pub sleeping: bool,
    pub foreground: bool,
    pub opacity: f64,
    pub immovable: bool,
    pub fixed_rotation: bool,
    pub vehicle: Option<Vehicle>,
    pub shapes: Vec<Item>,
    pub specials: Vec<Item>,
}

/// What a joint or trigger points at, by position in its list.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Ref {
    Shape(usize),
    Special(usize),
    Group(usize),
    Joint(usize),
    Trigger(usize),
}

#[derive(Clone, Debug)]
pub struct Joint {
    pub prismatic: bool,
    pub x: f64,
    pub y: f64,
    pub body1: Option<Ref>,
    pub body2: Option<Ref>,
    pub limit: bool,
    pub motor: bool,
    /// Pin: `upperAngle`/`lowerAngle`; sliding: `upperLimit`/`lowerLimit`.
    pub upper: f64,
    pub lower: f64,
    /// Pin: motor torque; sliding: motor force.
    pub force: f64,
    pub speed: f64,
    /// Sliding joints only.
    pub axis_angle: f64,
    pub collide_self: bool,
    pub vehicle_controlled: bool,
}

impl Joint {
    pub fn new(prismatic: bool) -> Joint {
        Joint {
            prismatic,
            x: 0.0,
            y: 0.0,
            body1: None,
            body2: None,
            limit: false,
            motor: false,
            upper: if prismatic { 100.0 } else { 90.0 },
            lower: if prismatic { -100.0 } else { -90.0 },
            force: 50.0,
            speed: 3.0,
            axis_angle: 90.0,
            collide_self: false,
            vehicle_controlled: true,
        }
    }

    pub fn set_upper(&mut self, v: f64) {
        let max = if self.prismatic { 8000.0 } else { 180.0 };
        self.upper = if v > max { max } else if v < 0.0 { 0.0 } else { v };
    }

    pub fn set_lower(&mut self, v: f64) {
        let max = if self.prismatic { 8000.0 } else { 180.0 };
        let v = if v > 0.0 { -v } else { v };
        self.lower = if v < -max { -max } else { v };
    }

    pub fn set_force(&mut self, v: f64) {
        self.force = if v > 100_000.0 { 100_000.0 } else { v };
    }

    pub fn set_speed(&mut self, v: f64) {
        let max = if self.prismatic { 50.0 } else { 20.0 };
        self.speed = if v > max { max } else if v < -max { -max } else { v };
    }
}

#[derive(Clone, Debug)]
pub struct Action {
    pub index: usize,
    /// `None` for a parameter the level does not give.
    pub params: Vec<Option<Value>>,
}

#[derive(Clone, Debug)]
pub struct Target {
    pub target: Ref,
    pub actions: Vec<Action>,
}

#[derive(Clone, Debug)]
pub struct Trigger {
    pub x: f64,
    pub y: f64,
    pub width: f64,
    pub height: f64,
    pub angle: f64,
    pub triggered_by: f64,
    /// 1 activate object, 2 play sound, 3 victory.
    pub kind: u8,
    pub repeat: f64,
    /// Kept as written when in range, like the original.
    pub interval: Value,
    pub start_disabled: bool,
    pub delay: f64,
    /// Index into the original's sound list.
    pub sound: i64,
    pub sound_location: f64,
    pub panning: f64,
    pub volume: f64,
    pub targets: Vec<Target>,
}

#[derive(Clone, Debug)]
pub struct Info {
    pub x: f64,
    pub y: f64,
    pub character: f64,
    pub force_character: bool,
    pub hide_vehicle: bool,
    pub backdrop: f64,
    pub background: f64,
}

impl Default for Info {
    /// A new level in the original editor: the start marker at (300, 100 + canvas height / 2).
    fn default() -> Info {
        Info { x: 300.0, y: 5100.0, character: 1.0, force_character: false, hide_vehicle: false, backdrop: 0.0, background: 16_777_215.0 }
    }
}

#[derive(Clone, Debug, Default)]
pub struct Document {
    pub info: Info,
    pub shapes: Vec<Item>,
    pub specials: Vec<Item>,
    pub groups: Vec<Group>,
    pub joints: Vec<Joint>,
    pub triggers: Vec<Trigger>,
}

impl Document {
    /// `buildLevel`.
    pub fn parse(xml: &str) -> Result<Document> {
        let doc = roxmltree::Document::parse(xml).context("level XML")?;
        let root = doc.root_element();
        let info = child(root, "info").context("level without info")?;
        let version = number(info, "v").unwrap_or(f64::NAN);
        let mut out = Document::default();
        // vertex lists are written once and then referred to by id
        let mut shared = [std::collections::HashMap::new(), std::collections::HashMap::new()];
        for n in section(root, "shapes", "sh") {
            out.shapes.push(read_shape(n, false, version, &mut shared)?);
        }
        for n in section(root, "specials", "sp") {
            out.specials.push(read_special(n, false)?);
        }
        for g in section(root, "groups", "g") {
            let int = |a: &str| number(g, a).map_or(f64::NAN, f64::trunc);
            let flag = |a: &str| g.attribute(a) == Some("t");
            let vehicle = flag("v").then(|| {
                let v = |a: &str, lo: f64, hi: f64| clamp(number(g, a).map_or(0.0, f64::trunc), Some(lo), Some(hi));
                Vehicle {
                    space_action: v("sb", 0.0, 3.0),
                    shift_action: v("sh", 0.0, 3.0),
                    ctrl_action: v("ct", 0.0, 3.0),
                    acceleration: v("a", 1.0, 10.0),
                    leaning_strength: v("l", 0.0, 10.0),
                    character_pose: v("cp", 0.0, 3.0),
                    lock_joints: flag("lo"),
                }
            });
            let mut group = Group {
                x: number(g, "x").unwrap_or(f64::NAN),
                y: number(g, "y").unwrap_or(f64::NAN),
                angle: round_angle(int("r")),
                offset: [number(g, "ox").unwrap_or(f64::NAN), number(g, "oy").unwrap_or(f64::NAN)],
                sleeping: flag("s"),
                foreground: flag("f"),
                opacity: match g.attribute("o") {
                    Some(o) if !o.is_empty() => js_round(100.0 * (0.01 * clamp(int("o"), Some(0.0), Some(100.0)))),
                    _ => 100.0,
                },
                immovable: flag("im"),
                fixed_rotation: flag("fr"),
                vehicle,
                shapes: Vec::new(),
                specials: Vec::new(),
            };
            for n in children(g, "sh") {
                group.shapes.push(read_shape(n, true, version, &mut shared)?);
            }
            for n in children(g, "sp") {
                group.specials.push(read_special(n, true)?);
            }
            out.groups.push(group);
        }
        for j in section(root, "joints", "j") {
            let kind = number(j, "t").unwrap_or(f64::NAN);
            if kind != 0.0 && kind != 1.0 {
                continue;
            }
            let mut joint = Joint::new(kind == 1.0);
            joint.x = number(j, "x").unwrap_or(f64::NAN);
            joint.y = number(j, "y").unwrap_or(f64::NAN);
            if joint.prismatic {
                let a = number(j, "a").unwrap_or(f64::NAN);
                joint.axis_angle = wrap(a);
            }
            let body = |a: &str| -> Option<Ref> {
                let v = j.attribute(a)?;
                match v.chars().next()? {
                    's' => v[1..].parse().ok().map(Ref::Special),
                    'g' => v[1..].parse().ok().map(Ref::Group),
                    _ => v.parse().ok().map(Ref::Shape),
                }
            };
            joint.body1 = body("b1");
            joint.body2 = body("b2");
            joint.limit = j.attribute("l") == Some("t");
            joint.motor = j.attribute("m") == Some("t");
            joint.collide_self = j.attribute("c") == Some("t");
            joint.vehicle_controlled = j.attribute("v") != Some("f");
            let (upper, lower, force) = if joint.prismatic { ("ul", "ll", "fo") } else { ("ua", "la", "tq") };
            // (the limits are read with `parseInt`, the motor values with `parseFloat`)
            if let Some(v) = number(j, upper) {
                joint.set_upper(v.trunc());
            }
            if let Some(v) = number(j, lower) {
                joint.set_lower(v.trunc());
            }
            if let Some(v) = number(j, force) {
                joint.set_force(v);
            }
            if let Some(v) = number(j, "sp") {
                joint.set_speed(v);
            }
            out.joints.push(joint);
        }
        let triggers: Vec<_> = section(root, "triggers", "t").collect();
        // targets may be later triggers, whose kind decides their action list
        for &t in &triggers {
            out.triggers.push(read_trigger(t)?);
        }
        for (i, &t) in triggers.iter().enumerate() {
            let head = &out.triggers[i];
            if head.kind != 1 && head.triggered_by != 4.0 {
                continue;
            }
            let activates = head.kind == 1;
            let mut targets = Vec::new();
            for c in t.children().filter(Node::is_element) {
                let at = number(c, "i").context("target without index")? as usize;
                let target = match c.tag_name().name() {
                    "sh" => Ref::Shape(at),
                    "sp" => Ref::Special(at),
                    "g" => Ref::Group(at),
                    "j" => Ref::Joint(at),
                    _ => Ref::Trigger(at),
                };
                let counts = out.action_counts(target)?;
                let mut actions = Vec::new();
                if let (true, Some(counts)) = (activates, counts) {
                    // levels before 1.87 give one action as attributes of the target itself
                    let old = version < 1.87;
                    let written: Vec<Node> = if old { vec![c] } else { c.children().filter(Node::is_element).collect() };
                    for a in written {
                        let index = number(a, if old { "a" } else { "i" }).unwrap_or(0.0) as usize;
                        let params = (0..counts.get(index).copied().unwrap_or(0)).map(|p| a.attribute(format!("p{p}").as_str()).map(flag_or_number)).collect();
                        actions.push(Action { index: if index < counts.len() { index } else { 0 }, params });
                    }
                }
                targets.push(Target { target, actions });
            }
            out.triggers[i].targets = targets;
        }
        let flag = |a: &str| info.attribute(a) == Some("t");
        out.info = Info {
            x: number(info, "x").unwrap_or(f64::NAN),
            y: number(info, "y").unwrap_or(f64::NAN),
            character: number(info, "c").unwrap_or(f64::NAN),
            force_character: flag("f"),
            hide_vehicle: flag("h"),
            backdrop: number(info, "bg").map_or(f64::NAN, f64::trunc),
            background: match info.attribute("bgc") {
                Some(c) if !c.is_empty() => number(info, "bgc").map_or(f64::NAN, f64::trunc),
                _ => 16_777_215.0,
            },
        };
        Ok(out)
    }

    /// The action list of whatever `r` points at.
    pub fn action_counts(&self, r: Ref) -> Result<Option<&'static Vec<usize>>> {
        let s = schema();
        let named = |n: &str| s.actions.get(n).and_then(Option::as_ref);
        Ok(match r {
            Ref::Shape(i) => self.shapes.get(i).context("missing shape target")?.spec().actions.as_ref(),
            Ref::Special(i) => self.specials.get(i).context("missing special target")?.spec().actions.as_ref(),
            Ref::Group(i) if i < self.groups.len() => named("group"),
            Ref::Joint(i) => named(if self.joints.get(i).context("missing joint target")?.prismatic { "pris" } else { "pin" }),
            Ref::Trigger(i) if i < self.triggers.len() => named("trigger"),
            _ => bail!("missing target {r:?}"),
        })
    }

    /// `createXML().toXMLString()`.
    pub fn to_xml(&self) -> String {
        let s = schema();
        let i = &self.info;
        let mut root = Element::new("levelXML");
        let mut info = Element::new("info");
        for (k, v) in [
            ("v", js_number(s.version)),
            ("rv", s.version_string.clone()),
            ("x", js_number(i.x)),
            ("y", js_number(i.y)),
            ("c", js_number(i.character)),
            ("f", tf(i.force_character)),
            ("h", tf(i.hide_vehicle)),
            ("bg", js_number(i.backdrop)),
            ("bgc", js_number(i.background)),
            ("e", "1".into()),
        ] {
            info.attr(k, v);
        }
        root.children.push(info);
        let (mut polygons, mut arts) = (Vec::new(), Vec::new());
        let mut shape = |item: &Item, in_vehicle: bool| write_shape(item, in_vehicle, &mut polygons, &mut arts);
        push_section(&mut root, "shapes", self.shapes.iter().map(|x| shape(x, false)).collect());
        push_section(&mut root, "specials", self.specials.iter().map(write_special).collect());
        let groups = self
            .groups
            .iter()
            .map(|g| {
                let mut e = Element::new("g");
                for (k, v) in [
                    ("x", js_number(g.x)),
                    ("y", js_number(g.y)),
                    ("r", js_number(g.angle)),
                    ("ox", js_number(g.offset[0])),
                    ("oy", js_number(g.offset[1])),
                    ("s", tf(g.sleeping)),
                    ("f", tf(g.foreground)),
                    ("o", js_number(g.opacity)),
                    ("im", tf(g.immovable)),
                    ("fr", tf(g.fixed_rotation)),
                ] {
                    e.attr(k, v);
                }
                if let Some(v) = &g.vehicle {
                    for (k, v) in [
                        ("v", "t".to_string()),
                        ("sb", js_number(v.space_action)),
                        ("sh", js_number(v.shift_action)),
                        ("ct", js_number(v.ctrl_action)),
                        ("a", js_number(v.acceleration)),
                        ("l", js_number(v.leaning_strength)),
                        ("cp", js_number(v.character_pose)),
                        ("lo", tf(v.lock_joints)),
                    ] {
                        e.attr(k, v);
                    }
                }
                e.children.extend(g.shapes.iter().map(|x| shape(x, g.vehicle.is_some())));
                e.children.extend(g.specials.iter().map(write_special));
                e
            })
            .collect();
        push_section(&mut root, "groups", groups);
        push_section(&mut root, "joints", self.joints.iter().map(|j| self.write_joint(j)).collect());
        push_section(&mut root, "triggers", self.triggers.iter().map(|t| self.write_trigger(t)).collect());
        let mut out = String::new();
        root.write(&mut out, 0);
        out.pop();
        out
    }

    fn write_joint(&self, j: &Joint) -> Element {
        let mut e = Element::new("j");
        let body = |r: Option<Ref>| match r {
            Some(Ref::Shape(i)) => i.to_string(),
            Some(Ref::Special(i)) => format!("s{i}"),
            Some(Ref::Group(i)) => format!("g{i}"),
            _ => "-1".into(),
        };
        for (k, v) in [("t", u8::from(j.prismatic).to_string()), ("x", js_number(j.x)), ("y", js_number(j.y)), ("b1", body(j.body1)), ("b2", body(j.body2))] {
            e.attr(k, v);
        }
        if j.prismatic {
            e.attr("a", js_number(j.axis_angle));
        }
        let (upper, lower, force) = if j.prismatic { ("ul", "ll", "fo") } else { ("ua", "la", "tq") };
        for (k, v) in [("l", tf(j.limit)), (upper, js_number(j.upper)), (lower, js_number(j.lower)), ("m", tf(j.motor)), (force, js_number(j.force)), ("sp", js_number(j.speed)), ("c", tf(j.collide_self))] {
            e.attr(k, v);
        }
        // only a joint with a second body that touches a vehicle group is "vehicle attached"
        let vehicle = |r: Option<Ref>| matches!(r, Some(Ref::Group(i)) if self.groups.get(i).is_some_and(|g| g.vehicle.is_some()));
        if j.body2.is_some() && (vehicle(j.body1) || vehicle(j.body2)) {
            e.attr("v", tf(j.vehicle_controlled));
        }
        e
    }

    fn write_trigger(&self, t: &Trigger) -> Element {
        let mut e = Element::new("t");
        for (k, v) in [
            ("x", js_number(t.x)),
            ("y", js_number(t.y)),
            ("w", js_number(t.width)),
            ("h", js_number(t.height)),
            ("a", js_number(t.angle)),
            ("b", js_number(t.triggered_by)),
            ("t", t.kind.to_string()),
            ("r", js_number(t.repeat)),
            ("sd", tf(t.start_disabled)),
        ] {
            e.attr(k, v);
        }
        if t.repeat > 2.0 {
            e.attr("i", t.interval.text());
        }
        if t.kind == 1 {
            e.attr("d", js_number(t.delay));
        } else if t.kind == 2 {
            for (k, v) in [("s", t.sound.to_string()), ("d", js_number(t.delay)), ("l", js_number(t.sound_location)), ("p", js_number(t.panning)), ("v", js_number(t.volume))] {
                e.attr(k, v);
            }
        }
        if t.kind == 1 || t.triggered_by == 4.0 {
            for target in &t.targets {
                let (tag, i) = match target.target {
                    Ref::Shape(i) => ("sh", i),
                    Ref::Special(i) => ("sp", i),
                    Ref::Group(i) => ("g", i),
                    Ref::Joint(i) => ("j", i),
                    Ref::Trigger(i) => ("t", i),
                };
                let mut x = Element::new(tag);
                x.attr("i", i.to_string());
                if t.kind == 1 {
                    for a in &target.actions {
                        let mut y = Element::new("a");
                        y.attr("i", a.index.to_string());
                        for (p, v) in a.params.iter().enumerate() {
                            y.attr(&format!("p{p}"), v.as_ref().map_or_else(|| "undefined".into(), Value::text));
                        }
                        x.children.push(y);
                    }
                }
                e.children.push(x);
            }
        }
        e
    }
}

fn read_shape(n: Node, grouped: bool, version: f64, shared: &mut [std::collections::HashMap<i64, Vec<String>>; 2]) -> Result<Item> {
    let mut class = number(n, "t").context("shape without type")? as usize;
    if class == POLYGON && n.attribute("i") == Some("f") {
        class = ART;
    }
    let mut item = Item::new(false, class, grouped).context("unknown shape type")?;
    if n.attribute("i") == Some("f") {
        item.interactive = false;
    }
    item.vehicle_handle = n.attribute("h") == Some("t");
    if class == POLYGON || class == ART {
        let v = child(n, "v").context("polygon without vertices")?;
        let id = number(v, "id").unwrap_or(0.0) as i64;
        let list = shared[class - POLYGON].entry(id).or_insert_with(|| {
            let count = number(v, "n").unwrap_or(0.0) as usize;
            (0..count).map(|k| v.attribute(format!("v{k}").as_str()).unwrap_or("").to_string()).collect()
        });
        let separator = if version < 1.84 { '.' } else { '_' };
        let points = list
            .iter()
            .map(|s| {
                let p: Vec<&str> = s.split(separator).collect();
                let at = |k: usize| p.get(k).and_then(|x| x.parse::<f64>().ok()).unwrap_or(f64::NAN);
                let pair = |k: usize| if class == ART && p.get(k).is_some_and(|x| !x.is_empty()) { [at(k), at(k + 1)] } else { [0.0, 0.0] };
                [[at(0), at(1)], pair(2), pair(4)]
            })
            .collect::<Vec<_>>();
        if points.len() < 2 {
            bail!("a polygon needs two vertices");
        }
        item.vertices = Some(Vertices { id, filled: v.attribute("f") == Some("t"), points });
        // until the level says otherwise they are as large as their vertices
        for (axis, name) in ["shapeWidth", "shapeHeight"].into_iter().enumerate() {
            if let Some(i) = item.index(name) {
                item.values[i] = Value::Num(js_round(item.default_size(axis)));
            }
        }
    }
    for (i, (name, _, _)) in item.spec().props.iter().enumerate() {
        match n.attribute(format!("p{i}").as_str()) {
            Some("") | None => {}
            Some(text) => item.set(name, flag_or_number(text)),
        }
    }
    Ok(item)
}

fn read_special(n: Node, grouped: bool) -> Result<Item> {
    let class = number(n, "t").context("special without type")? as usize;
    let mut item = Item::new(true, class, grouped).context("unknown special type")?;
    for (i, (name, default, _)) in item.spec().props.iter().enumerate() {
        let key = format!("p{i}");
        let attribute = n.attribute(key.as_str());
        let cdata = child(n, &key).map(|c| c.text().unwrap_or("").to_string());
        if matches!(default, Value::Text(_)) {
            let text = attribute.filter(|a| !a.is_empty()).map(str::to_string).or(cdata).unwrap_or_default();
            item.set(name, Value::Text(text));
        } else if let Some(text) = attribute.map(str::to_string).filter(|a| !a.is_empty()).or(cdata) {
            if !text.is_empty() {
                item.set(name, flag_or_number(&text));
            }
        }
    }
    Ok(item)
}

fn read_trigger(t: Node) -> Result<Trigger> {
    let num = |a: &str| number(t, a).unwrap_or(f64::NAN);
    let kind = num("t") as u8;
    if !(1..=3).contains(&kind) {
        bail!("trigger type out of range");
    }
    let side = |v: f64| js_round(100.0 * clamp(v / 100.0, Some(0.05), Some(50.0)));
    let repeat = clamp(num("r").trunc(), Some(1.0), Some(4.0));
    let mut out = Trigger {
        x: num("x"),
        y: num("y"),
        width: side(num("w")),
        height: side(num("h")),
        angle: wrap(num("a")),
        triggered_by: clamp(num("b").trunc(), Some(1.0), Some(6.0)),
        kind,
        repeat,
        interval: Value::Num(1.0),
        start_disabled: t.attribute("sd") == Some("t"),
        delay: 0.0,
        sound: 0,
        sound_location: 1.0,
        panning: 0.0,
        volume: 1.0,
        targets: Vec::new(),
    };
    if repeat > 2.0 {
        if let Some(i) = t.attribute("i") {
            let v = Value::Text(i.into()).number();
            out.interval = if v < 0.1 { Value::Num(0.1) } else if v > 30.0 { Value::Num(30.0) } else { Value::Text(i.into()) };
        }
    }
    let delay = |v: f64| clamp(v, Some(0.0), Some(30.0));
    if kind == 1 {
        out.delay = delay(num("d"));
    } else if kind == 2 {
        let s = num("s").trunc();
        out.sound = if (0.0..SOUNDS).contains(&s) { s as i64 } else { -1 };
        out.delay = delay(num("d"));
        out.volume = clamp(num("v"), Some(0.0), Some(1.0));
        out.sound_location = clamp(num("l"), Some(1.0), Some(2.0));
        out.panning = clamp(num("p"), Some(-1.0), Some(1.0));
    }
    Ok(out)
}

fn write_vertices(item: &Item, v: &Vertices, seen: &mut Vec<i64>) -> Element {
    let mut e = Element::new("v");
    e.attr("f", tf(v.filled));
    e.attr("id", v.id.to_string());
    if !seen.contains(&v.id) {
        seen.push(v.id);
        e.attr("n", v.points.len().to_string());
        for (k, [p, a, b]) in v.points.iter().enumerate() {
            let mut s = format!("{}_{}", js_number(p[0]), js_number(p[1]));
            if item.class == ART && [a[0], a[1], b[0], b[1]].iter().any(|&h| h != 0.0) {
                for h in [a[0], a[1], b[0], b[1]] {
                    s.push('_');
                    s.push_str(&js_number(h));
                }
            }
            e.attr(&format!("v{k}"), s);
        }
    }
    e
}

fn write_shape(item: &Item, in_vehicle: bool, polygons: &mut Vec<i64>, arts: &mut Vec<i64>) -> Element {
    let mut e = Element::new("sh");
    e.attr("t", item.class.to_string());
    if !item.interactive {
        e.attr("i", "f".into());
    } else if in_vehicle {
        e.attr("h", tf(item.vehicle_handle));
    }
    for (i, value) in item.values.iter().enumerate() {
        let text = match value {
            Value::Bool(b) => tf(*b),
            other => fixed2(other.number()),
        };
        e.attr(&format!("p{i}"), text);
    }
    if let Some(v) = &item.vertices {
        e.children.push(write_vertices(item, v, if item.class == ART { arts } else { polygons }));
    }
    e
}

fn write_special(item: &Item) -> Element {
    let mut e = Element::new("sp");
    e.attr("t", item.class.to_string());
    for (i, ((name, _, _), value)) in item.spec().props.iter().zip(&item.values).enumerate() {
        let key = format!("p{i}");
        match value {
            Value::Bool(b) => e.attr(&key, tf(*b)),
            Value::Text(s) if s == "true" || s == "false" => e.attr(&key, tf(s == "true")),
            Value::Text(s) if name == "caption" || parse_float(s).is_nan() => e.children.push(Element::cdata(&key, s)),
            Value::Text(s) => match s.parse::<f64>() {
                Ok(n) => e.attr(&key, js_number(n)),
                Err(_) => e.children.push(Element::cdata(&key, s)),
            },
            Value::Num(n) => e.attr(&key, js_number(*n)),
            Value::Null => e.attr(&key, "null".into()),
        }
    }
    e
}

struct Element {
    name: String,
    attributes: Vec<(String, String)>,
    children: Vec<Element>,
    cdata: Option<String>,
}

impl Element {
    fn new(name: &str) -> Element {
        Element { name: name.into(), attributes: Vec::new(), children: Vec::new(), cdata: None }
    }

    fn cdata(name: &str, text: &str) -> Element {
        Element { cdata: Some(text.into()), ..Element::new(name) }
    }

    fn attr(&mut self, name: &str, value: String) {
        self.attributes.push((name.into(), value));
    }

    /// E4X pretty printing: four spaces per level.
    fn write(&self, out: &mut String, depth: usize) {
        let pad = "    ".repeat(depth);
        out.push_str(&pad);
        out.push('<');
        out.push_str(&self.name);
        for (k, v) in &self.attributes {
            let v = v.replace('&', "&amp;").replace('<', "&lt;").replace('"', "&quot;");
            out.push_str(&format!(" {k}=\"{v}\""));
        }
        match &self.cdata {
            Some(text) if !text.is_empty() => out.push_str(&format!("><![CDATA[{}]]></{}>\n", text.replace("]]>", "]]]]><![CDATA[>"), self.name)),
            _ if self.children.is_empty() => out.push_str("/>\n"),
            _ => {
                out.push_str(">\n");
                for c in &self.children {
                    c.write(out, depth + 1);
                }
                out.push_str(&format!("{pad}</{}>\n", self.name));
            }
        }
    }
}

fn push_section(root: &mut Element, name: &str, children: Vec<Element>) {
    if !children.is_empty() {
        root.children.push(Element { children, ..Element::new(name) });
    }
}

fn child<'a, 'i>(n: Node<'a, 'i>, name: &str) -> Option<Node<'a, 'i>> {
    n.children().find(|c| c.has_tag_name(name))
}

fn children<'a, 'i: 'a>(n: Node<'a, 'i>, name: &'a str) -> impl Iterator<Item = Node<'a, 'i>> {
    n.children().filter(move |c| c.has_tag_name(name))
}

/// The elements `tag` of the first `name` section.
fn section<'a, 'i: 'a>(root: Node<'a, 'i>, name: &str, tag: &'a str) -> impl Iterator<Item = Node<'a, 'i>> {
    child(root, name).into_iter().flat_map(move |s| children(s, tag))
}

/// JavaScript's `parseFloat`: the longest numeric prefix.
fn parse_float(s: &str) -> f64 {
    let s = s.trim_start();
    (1..=s.len()).rev().filter(|&n| s.is_char_boundary(n)).find_map(|n| s[..n].parse::<f64>().ok().filter(|v| v.is_finite())).unwrap_or(f64::NAN)
}

fn number(n: Node, attribute: &str) -> Option<f64> {
    n.attribute(attribute).map(parse_float)
}

fn flag_or_number(text: &str) -> Value {
    match text {
        "t" => Value::Bool(true),
        "f" => Value::Bool(false),
        _ => {
            let v = parse_float(text);
            if v.is_nan() { Value::Text(text.into()) } else { Value::Num(v) }
        }
    }
}

fn clamp(v: f64, lo: Option<f64>, hi: Option<f64>) -> f64 {
    match (lo, hi) {
        (Some(lo), _) if v < lo => lo,
        (_, Some(hi)) if v > hi => hi,
        _ => v,
    }
}

/// `Math.round`.
fn js_round(v: f64) -> f64 {
    let r = (v + 0.5).floor();
    if r == 0.0 { 0.0 } else { r }
}

fn wrap(mut a: f64) -> f64 {
    if a > 180.0 {
        a -= 360.0;
    }
    if a < -180.0 {
        a += 360.0;
    }
    a
}

/// `_setAngle` and the display object's rotation, which is held in radians.
fn round_angle(a: f64) -> f64 {
    js_round(wrap(a)) * (PI / 180.0) * (180.0 / PI)
}

fn tf(b: bool) -> String {
    if b { "t".into() } else { "f".into() }
}

/// JavaScript's `String(number)`.
pub fn js_number(v: f64) -> String {
    if v.is_nan() {
        "NaN".into()
    } else if v.is_infinite() {
        if v > 0.0 { "Infinity".into() } else { "-Infinity".into() }
    } else if v == 0.0 {
        "0".into()
    } else if v.abs() < 1e-6 || v.abs() >= 1e21 {
        let s = format!("{v:e}");
        if s.contains("e-") { s } else { s.replace('e', "e+") }
    } else {
        v.to_string()
    }
}

/// `Number(v).toFixed(2).replace(/\.0+$/, "")`.
fn fixed2(v: f64) -> String {
    if !v.is_finite() || v.abs() >= 1e21 {
        return js_number(v);
    }
    // toFixed rounds an exact half away from zero, Rust to even; only multiples of 1/8 can be exact halves
    let eighths = v * 8.0;
    let v = if eighths.fract() == 0.0 && (eighths % 2.0).abs() == 1.0 { v + 0.001f64.copysign(v) } else { v };
    let s = if v == 0.0 { "0.00".to_string() } else { format!("{v:.2}") };
    s.strip_suffix(".00").map(str::to_string).unwrap_or(s)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn numbers_are_written_like_javascript() {
        assert_eq!(fixed2(0.125), "0.13");
        assert_eq!(fixed2(-0.125), "-0.13");
        assert_eq!(fixed2(1.5), "1.50");
        assert_eq!(fixed2(-0.001), "-0");
        assert_eq!(fixed2(-0.0), "0");
        assert_eq!(js_number(1e-7), "1e-7");
        assert_eq!(js_number(round_angle(15.0)), "14.999999999999998");
        assert_eq!(parse_float("12px"), 12.0);
    }
}
